  CarnivalPopup FindPopup(string kind)=>Array.Find(FindObjectsByType<CarnivalPopup>(FindObjectsSortMode.None),p=>p.Kind.ToString()==kind);
  void Inspect(string kind){Canvas.ForceUpdateCanvases();var popup=FindPopup(kind);Check(popup!=null,"Native "+kind+" is active");if(popup==null)return;InspectSafeFrame(popup,kind);Check(GameObject.Find("KEEP_PLAYING")==null&&GameObject.Find("FEATURE_PLAY")==null,"No dismiss-only text button: "+kind);var point=new PointerEventData(events){position=new Vector2(CrispUI.Width*.5f,CrispUI.SafeArea.yMax-20),button=PointerEventData.InputButton.Left};var outsideHits=new List<RaycastResult>();events.RaycastAll(point,outsideHits);var outsideTarget=outsideHits.Count==0?null:ExecuteEvents.GetEventHandler<IPointerClickHandler>(outsideHits[0].gameObject);if(outsideTarget!=null)ExecuteEvents.Execute(outsideTarget,point,ExecuteEvents.pointerClickHandler);ExecuteEvents.Execute(popup.CloseButton.gameObject,new BaseEventData(events),ExecuteEvents.cancelHandler);Check(popup.gameObject.activeInHierarchy,"Outside/cancel do not dismiss "+kind);foreach(var button in popup.GetComponentsInChildren<Button>()){if(!button.IsActive())continue;var b=Bounds(button.GetComponent<RectTransform>());var safe=CrispUI.SafeArea;Check(b.xMin>=safe.xMin-1&&b.xMax<=safe.xMax+1&&b.yMin>=safe.yMin-1&&b.yMax<=safe.yMax+1,kind+" action fits safe area: "+button.name);Check(b.width>=43.9f*Mathf.Max(1,CrispUI.Width/390f)&&b.height>=43.9f*Mathf.Max(1,CrispUI.Width/390f),kind+" touch target: "+button.name);}foreach(var image in popup.GetComponentsInChildren<Image>())if(image.name=="Bowling emblem"||image.name=="Broken heart"||image.name=="Restart arrow")Check(image.sprite!=null,"Decorative sprite exists: "+image.name);foreach(var text in popup.GetComponentsInChildren<Text>()){if(!string.IsNullOrEmpty(text.text)&&!text.name.Contains("state")){Check(text.preferredHeight<=text.rectTransform.rect.height+2,"Text fits: "+kind+" / "+text.name);var mesh=text.canvasRenderer.GetMesh();Check(mesh!=null&&mesh.vertexCount>0,"Text renders glyphs: "+kind+" / "+text.name);}}}
  Rect Bounds(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);Vector2 a=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,c[0]),b=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,c[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
  bool Tap(GameObject expected){Canvas.ForceUpdateCanvases();var p=new PointerEventData(events){position=Bounds(expected.GetComponent<RectTransform>()).center,button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();events.RaycastAll(p,hits);var target=hits.Count==0?null:ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits[0].gameObject);Check(target==expected,"Raycast reaches "+expected.name);if(target==expected)ExecuteEvents.Execute(target,p,ExecuteEvents.pointerClickHandler);return target==expected;}
  bool TapAt(Vector2 position,GameObject expected){Canvas.ForceUpdateCanvases();var p=new PointerEventData(events){position=position,button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();events.RaycastAll(p,hits);var target=hits.Count==0?null:ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits[0].gameObject);Check(target==expected,"Pointer reaches "+expected.name);if(target==expected)ExecuteEvents.Execute(target,p,ExecuteEvents.pointerClickHandler);return target==expected;}
  void Click(string name){var o=GameObject.Find(name);Check(o!=null,"Action exists: "+name);if(o!=null)Tap(o);}
  void Board(int level){game.GetComponent<AdventureHUD>().Close();game.Hud.HideResult();game.SetMenu(false);game.LoadLevel(level);game.Hud.ShowGame();Time.timeScale=1;}
  void Size(Vector2Int s){CrispUI.ReviewSize=s;CrispUI.ReviewSafeArea=s.x==1170?new Rect(0,102,s.x,s.y-243):new Rect(0,0,s.x,s.y);if(screen!=null){screen.Release();Destroy(screen);}screen=new RenderTexture(s.x,s.y,24);screen.Create();game.Camera.targetTexture=screen;game.Hud.UICamera.targetTexture=screen;}
  void Capture(string name){Canvas.ForceUpdateCanvases();var old=RenderTexture.active;game.Camera.Render();game.Hud.UICamera.Render();RenderTexture.active=screen;var t=new Texture2D(screen.width,screen.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,screen.width,screen.height),0,0);t.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),t.EncodeToPNG());Destroy(t);RenderTexture.active=old;}
  void OnLog(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error){Check(false,message+"\n"+stack);Restore();Application.Quit(1);}}
  void Save(){if(folder!=null)File.WriteAllText(Path.Combine(folder,"verification.json"),JsonUtility.ToJson(report,true));}
  void Restore(){if(restored)return;restored=true;foreach(var s in saved)if(!s.exists)PlayerPrefs.DeleteKey(s.key);else if(s.integer)PlayerPrefs.SetInt(s.key,int.Parse(s.value));else PlayerPrefs.SetString(s.key,s.value);PlayerPrefs.Save();report.restored=true;}
  void OnApplicationQuit(){Restore();}void OnDestroy(){Application.logMessageReceived-=OnLog;Restore();CrispUI.ReviewSize=null;CrispUI.ReviewSafeArea=null;CrispUI.ReviewReducedMotion=null;if(events!=null)events.enabled=true;}
 }
